import math

def triangle_properties(a, b, c):
    # Validate sides
    if a <= 0 or b <= 0 or c <= 0:
        return 'invalid'
    if a + b <= c or a + c <= b or b + c <= a:
        return 'invalid'

    # Determine kind
    if a == b == c:
        kind = 'equilateral'
    elif a == b or a == c or b == c:
        kind = 'isosceles'
    else:
        kind = 'scalene'

    # Perimeter and semi-perimeter
    perimeter = a + b + c
    s = perimeter / 2.0

    # Heron's formula
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))

    return (kind, round(area, 2), round(perimeter, 2))
