def spiral_diagonal_sum(grid):
    n = len(grid)
    if n == 0:
        return 0
    m = len(grid[0])
    if m == 0:
        return 0

    total = 0
    top, bottom = 0, n - 1
    left, right = 0, m - 1

    while top <= bottom and left <= right:
        # Top row: left -> right
        for c in range(left, right + 1):
            r = top
            if r == c or r + c == m - 1:
                total += grid[r][c]

        # Right column: top+1 -> bottom
        for r in range(top + 1, bottom + 1):
            c = right
            if r == c or r + c == m - 1:
                total += grid[r][c]

        # Bottom row: right-1 -> left (only if bottom > top)
        if bottom > top:
            for c in range(right - 1, left - 1, -1):
                r = bottom
                if r == c or r + c == m - 1:
                    total += grid[r][c]

        # Left column: bottom-1 -> top+1 (only if right > left)
        if right > left:
            for r in range(bottom - 1, top, -1):
                c = left
                if r == c or r + c == m - 1:
                    total += grid[r][c]

        top += 1
        bottom -= 1
        left += 1
        right -= 1

    return total
```

