from collections import deque

def simulate_deque(operations: list[str], capacity: int) -> list[int | None]:
    dq = deque()
    results = []

    for op in operations:
        if op.startswith('push_front'):
            _, val = op.split()
            val = int(val)
            if len(dq) == capacity:
                dq.pop()  # remove from back
            dq.appendleft(val)
        elif op.startswith('push_back'):
            _, val = op.split()
            val = int(val)
            if len(dq) == capacity:
                dq.popleft()  # remove from front
            dq.append(val)
        elif op == 'pop_front':
            if dq:
                results.append(dq.popleft())
            else:
                results.append(None)
        elif op == 'pop_back':
            if dq:
                results.append(dq.pop())
            else:
                results.append(None)
        elif op == 'peek_front':
            results.append(dq[0] if dq else None)
        elif op == 'peek_back':
            results.append(dq[-1] if dq else None)
        elif op == 'size':
            results.append(len(dq))

    return results
