from itertools import combinations

def count_valid_groups(words: list[str], k: int) -> int:
    n = len(words)
    if k > n or k <= 0:
        return 0

    # Precompute compatibility between each pair of words by index
    compatible = [[False] * n for _ in range(n)]
    for i in range(n):
        set_i = set(words[i])
        for j in range(i + 1, n):
            if set_i & set(words[j]):
                compatible[i][j] = True
                compatible[j][i] = True

    count = 0
    for group in combinations(range(n), k):
        valid = True
        for i in range(k):
            for j in range(i + 1, k):
                if not compatible[group[i]][group[j]]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            count += 1
    return count
