def count_peak_components(n: int, edges: list[tuple[int, int]], values: list[int]) -> int:
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    for u, v in edges:
        union(u, v)

    # For each component root, track max value and count of nodes attaining it
    comp_max = {}
    comp_max_count = {}

    for i in range(n):
        r = find(i)
        val = values[i]
        if r not in comp_max or val > comp_max[r]:
            comp_max[r] = val
            comp_max_count[r] = 1
        elif val == comp_max[r]:
            comp_max_count[r] += 1

    count = 0
    for r in comp_max:
        if comp_max_count[r] == 1:
            count += 1

    return count
