            continue

        if state == 'idle':
            if action == 'start':
                if guard == 'ok':
                    state = 'running'
                    log.append('started')
                else:
                    log.append('start-blocked')
            elif action == 'reset':
                if guard == 'ok':
                    counter = 0
                    log.append('reset')
                else:
                    log.append('reset-blocked')

        elif state == 'running':
            if action == 'tick':
                if guard == 'ok':
                    counter += 1
                    log.append('ticked')
                else:
                    log.append('tick-skipped')
            elif action == 'stop':
                if guard == 'ok':
                    state = 'idle'
                    log.append('stopped')
                else:
                    log.append('stop-blocked')

    return (state, counter, log)
