from math import gcd

def count_coprime_pairs(n: int) -> int:
    if n < 2:
        return 0

    # Compute Euler's totient for all numbers up to n
    phi = list(range(n + 1))
    for i in range(2, n + 1):
        if phi[i] == i:  # i is prime
            for j in range(i, n + 1, i):
                phi[j] -= phi[j] // i

    # Number of coprime pairs (a, b) with a < b <= n
    # equals sum_{b=2}^n phi(b)
    return sum(phi[2:n+1])
