def count_common_pairs(groups):
    from collections import defaultdict

    id_to_groups = defaultdict(list)
    for idx, group in enumerate(groups):
        for gid in group:
            id_to_groups[gid].append(idx)

    common_pairs = set()
    for indices in id_to_groups.values():
        n = len(indices)
        for i in range(n):
            for j in range(i + 1, n):
                a, b = indices[i], indices[j]
                if a > b:
                    a, b = b, a
                common_pairs.add((a, b))

    return len(common_pairs)
