from datetime import datetime, timedelta

def business_minutes_between(start: str, end: str, holidays: list[str]) -> int:
    fmt = "%Y-%m-%d %H:%M"
    start_dt = datetime.strptime(start, fmt)
    end_dt = datetime.strptime(end, fmt)

    if end_dt <= start_dt:
        return 0

    holiday_set = set(holidays)

    def is_business_day(d):
        if d.weekday() >= 5:
            return False
        if d.strftime("%Y-%m-%d") in holiday_set:
            return False
        return True

    def minutes_in_day(day, day_start, day_end):
        # Business window for that day
        b_start = day.replace(hour=9, minute=0)
        b_end = day.replace(hour=17, minute=0)

        s = max(day_start, b_start)
        e = min(day_end, b_end)

        if e > s:
            return int((e - s).total_seconds() // 60)
        return 0

    total = 0
    current_day = start_dt.replace(hour=0, minute=0, second=0, microsecond=0)
    last_day = end_dt.replace(hour=0, minute=0, second=0, microsecond=0)

    while current_day <= last_day:
        if is_business_day(current_day):
            if current_day == start_dt.replace(hour=0, minute=0, second=0, microsecond=0) and current_day == last_day:
                total += minutes_in_day(current_day, start_dt, end_dt)
            elif current_day == start_dt.replace(hour=0, minute=0, second=0, microsecond=0):
                total += minutes_in_day(current_day, start_dt, current_day.replace(hour=23, minute=59, second=59))
            elif current_day == last_day:
                total += minutes_in_day(current_day, current_day, end_dt)
            else:
                total += 480
        current_day += timedelta(days=1)

    return total
