                valid = False
            else:
                parts = email.split('@')
                if len(parts) != 2:
                    valid = False
                else:
                    local, domain = parts
                    if not local_pattern.match(local):
                        valid = False
                    else:
                        labels = domain.split('.')
                        if len(labels) < 2:
                            valid = False
                        else:
