def sum_of_divisors_chain(n):
    if n <= 0:
        return 0

    def aliquot_sum(x):
        if x == 1:
            return 0
        total = 1
        i = 2
        while i * i <= x:
            if x % i == 0:
                total += i
                if i != x // i:
                    total += x // i
            i += 1
        return total

    seen = set()
    count = 0
    current = n

    while current not in seen and current != 1:
        seen.add(current)
        count += 1
        current = aliquot_sum(current)

    if current == 1:
        count += 1  # include 1 in the count
    elif current in seen:
        # cycle detected; don't double count the repeated value
        pass

    return count
