import re


def parse_log_entries(text: str) -> list[dict]:
    result = []
    line_re = re.compile(r'^\[([A-Za-z]+)\] (.+)$')
    key_re = re.compile(r'^[A-Za-z0-9_]+$')

    for raw_line in text.splitlines():
