            for token in fields_part.split():
                if '=' not in token:
                    continue
                key, value = token.split('=', 1)
                if not key or not key_re.match(key):
                    continue
                fields[key] = value

        result.append({
            'level': level,
            'message': message,
            'fields': fields,
        })

    return result
