def parse_log(text: str) -> list[dict]:
    result = []
    valid_levels = {"DEBUG", "INFO", "WARN", "ERROR"}

    for raw_line in text.split("\n"):
        line = raw_line.strip()
        if not line:
            continue

        # Parse level
        i = 0
        n = len(line)
        while i < n and line[i] != ' ':
            i += 1
        level = line[:i]
        if level not in valid_levels:
            raise ValueError(f"Invalid log level: {level!r}")

        fields = {}
        # Skip spaces (should be exactly one between tokens, but we tolerate leading space handling)
        while i < n:
            if line[i] != ' ':
                raise ValueError("Expected single space separator")
            i += 1
            if i >= n:
                raise ValueError("Trailing space")

            # Parse key
            key_start = i
            while i < n and (line[i].isalnum() or line[i] == '_'):
                i += 1
            key = line[key_start:i]
            if not key:
                raise ValueError("Missing key")
            if i >= n or line[i] != '=':
                raise ValueError(f"Missing '=' after key {key!r}")
            i += 1  # skip '='
            if key in fields:
                raise ValueError(f"Duplicate key: {key!r}")

            # Parse value
            if i < n and line[i] == '"':
                # Quoted value
                i += 1
                chars = []
                closed = False
                while i < n:
                    c = line[i]
                    if c == '\\':
                        if i + 1 >= n:
                            raise ValueError("Dangling escape in quoted value")
                        nxt = line[i + 1]
                        if nxt == '"':
                            chars.append('"')
                        elif nxt == '\\':
                            chars.append('\\')
                        else:
                            raise ValueError(f"Invalid escape sequence: \\{nxt}")
                        i += 2
                    elif c == '"':
                        i += 1
                        closed = True
                        break
                    else:
                        chars.append(c)
                        i += 1
                if not closed:
                    raise ValueError("Unterminated quoted value")
                value = ''.join(chars)
                # After closing quote must be end of line or a space
                if i < n and line[i] != ' ':
                    raise ValueError("Trailing characters after quoted value")
            else:
                # Unquoted value
                val_start = i
                while i < n and line[i] != ' ':
                    c = line[i]
                    if c in ('"', '\\'):
                        raise ValueError(f"Invalid character in unquoted value: {c!r}")
                    i += 1
                value = line[val_start:i]
                if not value:
                    raise ValueError(f"Empty value for key {key!r}")

            fields[key] = value

        result.append({"level": level, "fields": fields})

    return result
