def parse_config(text: str) -> dict:
    lines = text.splitlines()
    pos = 0

    def is_ident_start(c):
        return c.isalpha() or c == '_'

    def is_ident_char(c):
        return c.isalnum() or c == '_'

    def is_bare_char(c):
        return c.isalnum() or c in '_-.'

    def skip_ws(s, i):
        while i < len(s) and s[i] in ' \t':
            i += 1
        return i

    def parse_quoted(s, i):
        quote = s[i]
        i += 1
        out = []
        escapes = {'\\': '\\', "'": "'", '"': '"', 'n': '\n', 't': '\t'}
        while i < len(s):
            c = s[i]
            if c == '\\':
                i += 1
                if i >= len(s):
                    raise ValueError("unterminated escape")
                e = s[i]
                if e not in escapes:
                    raise ValueError("invalid escape sequence")
                out.append(escapes[e])
                i += 1
            elif c == quote:
                return ''.join(out), i + 1
            else:
                out.append(c)
                i += 1
        raise ValueError("unterminated quoted string")

    def parse_value(s, i):
        # returns (value, new_index)
        i = skip_ws(s, i)
        if i >= len(s):
            raise ValueError("missing value")
        c = s[i]
        if c in ('"', "'"):
            val, i = parse_quoted(s, i)
            return val, i
        if c == '[':
            i += 1
            items = []
            i = skip_ws(s, i)
            if i < len(s) and s[i] == ']':
                return items, i + 1
            while True:
                i = skip_ws(s, i)
                if i >= len(s):
                    raise ValueError("unterminated list")
                c2 = s[i]
                if c2 in ('"', "'"):
                    item, i = parse_quoted(s, i)
                elif is_bare_char(c2):
                    start = i
                    while i < len(s) and is_bare_char(s[i]):
                        i += 1
                    item = s[start:i]
                else:
                    raise ValueError("invalid list item")
                items.append(item)
                i = skip_ws(s, i)
                if i >= len(s):
                    raise ValueError("unterminated list")
                if s[i] == ',':
                    i += 1
                    continue
                elif s[i] == ']':
                    return items, i + 1
                else:
                    raise ValueError("expected , or ] in list")
        if is_bare_char(c):
            start = i
            while i < len(s) and is_bare_char(s[i]):
                i += 1
            return s[start:i], i
        raise ValueError("invalid value")

    def parse_key(s, i):
        i = skip_ws(s, i)
        if i >= len(s) or not is_ident_start(s[i]):
            raise ValueError("invalid key")
        start = i
        i += 1
        while i < len(s) and is_ident_char(s[i]):
            i += 1
        return s[start:i], i

    def check_trailing(s, i):
        i = skip_ws(s, i)
        if i < len(s):
            raise ValueError("trailing content")

    def parse_block(stack):
        nonlocal pos
        current = stack[-1]
        while pos < len(lines):
            line = lines[pos]
            stripped = line.strip()
            if stripped == '' or stripped.startswith('#'):
                pos += 1
                continue
            if stripped == '}':
                if len(stack) == 1:
                    raise ValueError("unmatched closing brace")
                pos += 1
                stack.pop()
                return
            # parse key
            key, i = parse_key(line, 0)
            i = skip_ws(line, i)
            if i >= len(line):
                raise ValueError("malformed assignment")
            if line[i] == '=':
                if key in current:
                    raise ValueError(f"duplicate key: {key}")
                i += 1
                val, i = parse_value(line, i)
                check_trailing(line, i)
                current[key] = val
                pos += 1
            elif line[i] == '{':
                check_trailing(line, i + 1)
                if key in current:
                    raise ValueError(f"duplicate key: {key}")
                new_dict = {}
                current[key] = new_dict
                stack.append(new_dict)
                pos += 1
                parse_block(stack)
            else:
                raise ValueError("malformed line")

    root = {}
    stack = [root]
    parse_block(stack)
    if len(stack) != 1:
        raise ValueError("unclosed section at EOF")
    return root
```

