def analyze_sets(groups, queries):
    sets = [set(g) for g in groups]
    results = []
    for op, i, j in queries:
        a, b = sets[i], sets[j]
        if op == 'union':
            results.append(len(a | b))
        elif op == 'intersection':
            results.append(len(a & b))
        elif op == 'difference':
            results.append(len(a - b))
        elif op == 'symmetric_difference':
            results.append(len(a ^ b))
        else:
            raise ValueError(f"Unknown operation: {op}")
    return results
