def parse_log(lines):
    valid_levels = {"DEBUG", "INFO", "WARN", "ERROR"}
    events = []

    for line in lines:
        if not line.strip():
            continue

        # Parse level
        if not line.startswith("["):
            raise ValueError(f"Invalid log line: {line!r}")
        close_bracket = line.find("]")
        if close_bracket == -1:
            raise ValueError(f"Invalid log line: {line!r}")

        level = line[1:close_bracket]
        if level not in valid_levels:
            raise ValueError(f"Invalid level: {level!r}")

        remainder = line[close_bracket + 1:]
        if remainder.startswith(" "):
            remainder = remainder[1:]

        # Split message and attributes
        sep_index = remainder.find(" | ")
        if sep_index == -1:
            message = remainder
            attrs_str = ""
        else:
            message = remainder[:sep_index]
            attrs_str = remainder[sep_index + 3:]

        # Parse attributes
        attrs = {}
        i = 0
        n = len(attrs_str)
        while i < n:
            # Skip whitespace
            while i < n and attrs_str[i].isspace():
                i += 1
            if i >= n:
                break

            # Read key
            key_start = i
            while i < n and attrs_str[i] != '=' and not attrs_str[i].isspace():
                i += 1

            if i >= n or attrs_str[i] != '=':
                token_end = i
                while token_end < n and not attrs_str[token_end].isspace():
                    token_end += 1
                token = attrs_str[key_start:token_end]
                raise ValueError(f"Attribute token without '=': {token!r}")

            key = attrs_str[key_start:i]
            i += 1  # skip '='

            # Read value
            if i < n and attrs_str[i] == '"':
                i += 1
                value_start = i
                while i < n and attrs_str[i] != '"':
                    i += 1
                if i >= n:
                    raise ValueError(f"Unterminated quoted value for key {key!r}")
                value = attrs_str[value_start:i]
                i += 1  # skip closing quote
            else:
                value_start = i
                while i < n and not attrs_str[i].isspace():
                    i += 1
                value = attrs_str[value_start:i]

            attrs[key] = value

        events.append({"level": level, "message": message, "attrs": attrs})

    return events
```

