def count_squarefree_divisors(n: int) -> int:
    if n < 1:
        raise ValueError("n must be a positive integer")

    distinct_primes = 0
    p = 2
    while p * p <= n:
        if n % p == 0:
            distinct_primes += 1
            while n % p == 0:
                n //= p
        p += 1 if p == 2 else 2

    if n > 1:
        distinct_primes += 1

    return 1 << distinct_primes
