def count_reachable_components(adj):
    n = len(adj)
    if n == 0:
        return 0

    # Build a clean adjacency set, ignoring self-loops and duplicates.
    neighbors = [set() for _ in range(n)]
    has_edge = False
    for u in range(n):
        for v in adj[u]:
            if v != u:  # ignore self-loops
                neighbors[u].add(v)
                neighbors[v].add(u)
                has_edge = True

    if not has_edge:
        return 0

    visited = [False] * n
    components_with_edges = 0

    for start in range(n):
        if visited[start] or not neighbors[start]:
            continue
        # BFS
        stack = [start]
        visited[start] = True
        while stack:
            node = stack.pop()
            for nb in neighbors[node]:
                if not visited[nb]:
                    visited[nb] = True
                    stack.append(nb)
        components_with_edges += 1

    return components_with_edges
