import re


def parse_ledger(text: str) -> dict:
    account_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    amount_re = re.compile(r'^(0|[1-9][0-9]*)$')

    operations = []
    lines = text.split('\n')

    for idx, raw in enumerate(lines, start=1):
        stripped = raw.strip()
        if not stripped:
            continue
        if stripped.startswith('#'):
            continue

        tokens = stripped.split()
        if len(tokens) != 3:
            raise ValueError(f"Malformed line {idx}: expected 3 tokens")

        account, op, amount = tokens

        if not account_re.match(account):
            raise ValueError(f"Malformed line {idx}: invalid account name '{account}'")
        if op not in ('+', '-', '='):
            raise ValueError(f"Malformed line {idx}: invalid operator '{op}'")
        if not amount_re.match(amount):
            raise ValueError(f"Malformed line {idx}: invalid amount '{amount}'")

        operations.append((account, op, int(amount)))

    balances = {}
    for account, op, value in operations:
        current = balances.get(account, 0)
        if op == '+':
            balances[account] = current + value
        elif op == '-':
            balances[account] = current - value
        else:  # '='
            balances[account] = value

    return balances
