```python
def max_score(nums):
    n = len(nums)
    if n == 0:
        return 0

    memo = {}

    def dp(i, j):
        if i > j:
            return 0
        if (i, j) in memo:
            return memo[(i, j)]

        # Pick left coin
        pick_left = nums[i] + min(dp(i + 2, j), dp(i + 1, j - 1))
        # Pick right coin
        pick_right = nums[j] + min(dp(i + 1, j - 1), dp(i, j - 2))

        memo[(i, j)] = max(pick_left, pick_right)
        return memo[(i, j)]

    return dp(0, n - 1)
```

