def count_reachable_components(n: int, edges: list[tuple[int, int]]) -> int:
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    components = 0

    for start in range(n):
        if not visited[start]:
            components += 1
            # BFS from start
            stack = [start]
            visited[start] = True
            while stack:
                node = stack.pop()
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

    return components
```

