def count_paths(n: int, blocked: list) -> int:
    blocked_set = set(blocked)

    if n in blocked_set:
        return 0

    memo = {}

    def dp(pos):
        if pos in blocked_set:
            return 0
        if pos == 0:
            return 1
        if pos < 0:
            return 0
        if pos in memo:
            return memo[pos]

        result = dp(pos - 1) + dp(pos - 2)
        memo[pos] = result
        return result

    return dp(n)
