from datetime import datetime, timedelta

def business_minutes_between(start, end):
    fmt = '%Y-%m-%d %H:%M'
    start_dt = datetime.strptime(start, fmt)
    end_dt = datetime.strptime(end, fmt)

    if end_dt <= start_dt:
        return 0

    def is_workday(d):
        return d.weekday() < 5  # Monday=0 ... Friday=4

    def work_start(d):
        return d.replace(hour=9, minute=0, second=0, microsecond=0)

    def work_end(d):
        return d.replace(hour=17, minute=0, second=0, microsecond=0)

    total = timedelta(0)

    current_day = start_dt.date()
    last_day = end_dt.date()

    while current_day <= last_day:
        day_start = datetime.combine(current_day, datetime.min.time())
        if is_workday(day_start):
            ws = work_start(day_start)
            we = work_end(day_start)

            seg_start = max(start_dt, ws)
            seg_end = min(end_dt, we)

            if seg_end > seg_start:
                total += seg_end - seg_start

        current_day += timedelta(days=1)

    return int(total.total_seconds() // 60)
