import re

KEY_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
INT_RE = re.compile(r'^-?\d+$')


def parse_config(text: str) -> dict:
    root = {}
    # Stack of (indent, dict) for open sections.
    stack = [(-1, root)]

    lines = text.split('\n')
    for raw in lines:
        if raw.strip() == '':
            continue
        stripped = raw.lstrip(' ')
        if stripped.startswith('#'):
            continue

        indent = len(raw) - len(stripped)
        if indent % 2 != 0:
            raise ValueError("Indentation must be a multiple of 2 spaces")

        # Pop sections whose indent is >= current indent (we're leaving them).
        while len(stack) > 1 and stack[-1][0] >= indent:
            stack.pop()

        parent_indent, parent = stack[-1]

        # Determine required nesting: indent must be exactly parent_indent + 2
        # when inside a section, or 0 at top level.
        expected = parent_indent + 2 if parent_indent >= 0 else 0
        if indent != expected:
            raise ValueError("Invalid indentation level")

        # Parse the line content.
        if ':' in stripped and '=' not in stripped:
            # Section header: key:
            if not stripped.endswith(':'):
                raise ValueError("Malformed section header")
            key = stripped[:-1].strip()
            if not KEY_RE.match(key):
                raise ValueError(f"Invalid key: {key!r}")
            if key in parent:
                raise ValueError(f"Duplicate key: {key!r}")
            new_dict = {}
            parent[key] = new_dict
            stack.append((indent, new_dict))
        elif '=' in stripped:
            if stripped.count('=') < 1:
                raise ValueError("Malformed assignment")
            key_part, _, value_part = stripped.partition('=')
            key = key_part.strip()
            value_str = value_part.strip()
            if not KEY_RE.match(key):
                raise ValueError(f"Invalid key: {key!r}")
            if key in parent:
                raise ValueError(f"Duplicate key: {key!r}")

            # Parse value.
            if value_str.startswith('"'):
                if len(value_str) < 2 or not value_str.endswith('"'):
                    raise ValueError("Unterminated string")
                inner = value_str[1:-1]
                if '"' in inner:
                    raise ValueError("Embedded quote in string")
                value = inner
            elif value_str == 'true':
                value = True
            elif value_str == 'false':
                value = False
            elif INT_RE.match(value_str):
                value = int(value_str)
            else:
                raise ValueError(f"Invalid value: {value_str!r}")

            parent[key] = value
        else:
            raise ValueError(f"Malformed line: {stripped!r}")

    return root
```

