def simulate_stacks(operations: list[str]) -> tuple:
    A = []
    B = []

    for op in operations:
        if op.startswith('push '):
            _, val = op.split()
            A.append(int(val))
        elif op == 'popA':
            if A:
                A.pop()
        elif op == 'popB':
            if B:
                B.pop()
        elif op == 'moveAB':
            # Move all elements from A to B, preserving order such that
            # top of A becomes bottom of B.
            while A:
                B.append(A.pop())
        elif op == 'moveBA':
            while B:
                A.append(B.pop())
        elif op == 'swapTop':
            if A and B:
                A[-1], B[-1] = B[-1], A[-1]

    topA = A[-1] if A else None
    topB = B[-1] if B else None
    return (topA, topB)
