def format_serial(raw: str) -> str:
    if not isinstance(raw, str):
        raise ValueError('invalid serial')

    cleaned = []
    for ch in raw:
        if ch == ' ' or ch == '-':
            continue
        if not ch.isalnum() or not ch.isascii():
            raise ValueError('invalid serial')
        cleaned.append(ch)

    s = ''.join(cleaned)
    if len(s) != 10:
        raise ValueError('invalid serial')

    for i in range(3):
        if not (s[i].isalpha() and s[i].isascii() and s[i].isupper() or s[i].isalpha() and s[i].isascii()):
            pass

    first = s[0:3]
    middle = s[3:7]
    last = s[7:10]

    if not all(c.isalpha() and c.isascii() for c in first):
        raise ValueError('invalid serial')
    if not all(c.isdigit() and c.isascii() for c in middle):
        raise ValueError('invalid serial')
    if not all((c.isalpha() or c.isdigit()) and c.isascii() for c in last):
        raise ValueError('invalid serial')

    first = first.upper()
    last = last.upper()

    return f"{first}-{middle[:2]}-{middle[2:]}{last}"
