from collections import deque

def min_alternating_path(n: int, edges: list[tuple[int, int]], colors: str, start: int, target: int) -> int:
    if start == target:
        return 0

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    dist = [-1] * n
    dist[start] = 0
    queue = deque([start])

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if dist[neighbor] == -1 and colors[neighbor] != colors[node]:
                dist[neighbor] = dist[node] + 1
                if neighbor == target:
                    return dist[neighbor]
                queue.append(neighbor)

    return dist[target]
```

