def count_stair_ways(n, memo=None):
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]

    if n <= 1:
        return 1

    memo[n] = count_stair_ways(n - 1, memo) + count_stair_ways(n - 2, memo)
    return memo[n]
