from datetime import datetime, timedelta

def add_business_minutes(start: str, minutes: int) -> str:
    BUSINESS_START = 9 * 60      # 09:00 in minutes from midnight
    BUSINESS_END = 17 * 60       # 17:00 in minutes from midnight

    dt = datetime.strptime(start, '%Y-%m-%d %H:%M')

    def is_business_day(d):
        return d.weekday() < 5

    def next_business_start(d):
        # If before business hours on a weekday, move to 09:00 same day.
        # If at/after 17:00 or weekend, move to next weekday 09:00.
        if is_business_day(d) and d.hour * 60 + d.minute < BUSINESS_START:
            return d.replace(hour=9, minute=0)
        # advance to next day at 09:00 until a weekday
        d = d.replace(hour=9, minute=0) + timedelta(days=1)
        while not is_business_day(d):
            d += timedelta(days=1)
        return d

    # Normalize starting point into business time
    cur_minutes = dt.hour * 60 + dt.minute
    if not is_business_day(dt) or cur_minutes >= BUSINESS_END:
        dt = next_business_start(dt)
    elif cur_minutes < BUSINESS_START:
        dt = dt.replace(hour=9, minute=0)

    remaining = minutes

    while remaining > 0:
        cur_minutes = dt.hour * 60 + dt.minute
        available_today = BUSINESS_END - cur_minutes

        if remaining <= available_today:
            dt = dt + timedelta(minutes=remaining)
            remaining = 0
        else:
            remaining -= available_today
            # Move to next business day start
            dt = dt.replace(hour=9, minute=0) + timedelta(days=1)
            while not is_business_day(dt):
                dt += timedelta(days=1)

    return dt.strftime('%Y-%m-%d %H:%M')
