def parse_records(text: str) -> list[dict]:
    records = []
    for line in text.split("\n"):
        if not line.strip():
            continue

        parts = line.split(";")
        # A trailing semicolon produces an empty final part, which is malformed.
        record = {}
        for part in parts:
            pair = part.strip()
            if not pair:
                raise ValueError(f"Empty key=value pair in line: {line!r}")

            if "=" not in pair:
                raise ValueError(f"Missing '=' in pair: {pair!r}")

            key, value = pair.split("=", 1)
            key = key.strip()
            value = value.strip()

            if not key:
                raise ValueError(f"Empty key in pair: {pair!r}")
            if not value:
                raise ValueError(f"Empty value in pair: {pair!r}")
            if ";" in key or "=" in key:
                raise ValueError(f"Invalid key: {key!r}")
            if ";" in value or "=" in value:
                raise ValueError(f"Invalid value: {value!r}")
            if key in record:
                raise ValueError(f"Duplicate key: {key!r}")

            record[key] = value

        records.append(record)

    return records
```

```python
def count_common_pairs(groups):
    n = len(groups)
    if n < 2:
        return 0

    # Map each element to the list of set indices that contain it
    element_to_sets = {}
    for idx, group in enumerate(groups):
        for elem in group:
            element_to_sets.setdefault(elem, []).append(idx)

    # Use a set of pairs to avoid double counting
    common_pairs = set()
    for indices in element_to_sets.values():
        m = len(indices)
        if m < 2:
            continue
        for a in range(m):
            for b in range(a + 1, m):
                i, j = indices[a], indices[b]
                if i > j:
                    i, j = j, i
                common_pairs.add((i, j))

    return len(common_pairs)
```

