def collapse_repeats(s: str) -> str:
    while True:
        if not s:
            return s
        result = []
        i = 0
        n = len(s)
        changed = False
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            run_len = j - i
            if run_len >= 2:
                changed = True
            result.append(s[i])
            i = j
        s = ''.join(result)
        if not changed:
            return s
