def merge_intervals_with_metadata(intervals, metadata):
    if not intervals:
        return []

    # Pair each interval with its index and sort by start
    indexed = sorted(enumerate(intervals), key=lambda x: (x[1][0], x[1][1]))

    result = []

    cur_start, cur_end = indexed[0][1]
    cur_meta = dict(metadata.get(indexed[0][0], {}))

    for idx, (start, end) in indexed[1:]:
        if start <= cur_end + 1:
            # Merge
            if end > cur_end:
                cur_end = end
            # Combine metadata
            m = metadata.get(idx, {})
            for k, v in m.items():
                cur_meta[k] = cur_meta.get(k, 0) + v
        else:
            # Finalize current group
            cleaned = {k: v for k, v in cur_meta.items() if v != 0}
            result.append((cur_start, cur_end, cleaned))
            # Start new group
            cur_start, cur_end = start, end
            cur_meta = dict(metadata.get(idx, {}))

    # Append last group
    cleaned = {k: v for k, v in cur_meta.items() if v != 0}
    result.append((cur_start, cur_end, cleaned))

    return result
