from collections import deque

def bfs_layers(adj, sources):
    if not sources:
        return []

    n = len(adj)
    dist = [-1] * n
    q = deque()

    for s in sources:
        if 0 <= s < n and dist[s] == -1:
            dist[s] = 0
            q.append(s)

    layers_dict = {}
    while q:
        u = q.popleft()
        d = dist[u]
        layers_dict.setdefault(d, []).append(u)
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = d + 1
                q.append(v)

    result = []
    k = 0
    while k in layers_dict:
        result.append(sorted(layers_dict[k]))
        k += 1

    return result
```

