def run_state_machine(transitions, start_state, events):
    state = start_state
    outputs = []

    for event in events:
        if state not in transitions or event not in transitions[state]:
            break

        transition = transitions[state][event]

        if isinstance(transition, tuple):
            next_state, output = transition
            outputs.append(output)
        else:
            next_state = transition

        state = next_state

    return state, outputs
