def count_paths(n: int) -> int:
    memo = {}

    def helper(k: int) -> int:
        if k <= 1:
            return 1
        if k in memo:
            return memo[k]
        memo[k] = helper(k - 1) + helper(k - 2)
        return memo[k]

    return helper(n)
```

